steps.script:
var ph = PhaseManager.get_current_phase_instance()
if ph.get("_awaiting_reroll_decision"):
	NetworkIntegration.route_action({"type": "DECLINE_COMMAND_REROLL", "actor_unit_id": "U_BIG_MEK_A", "player": 1})
for c in tree.root.get_children():
	if c is Window and c != tree.root and str(c.name).contains("Reroll"):
		c.hide()
		c.queue_free()
return true

var am = PhaseManager.get_current_phase_instance().active_moves.get("U_BIG_MEK_A", {})
print("[wp-o6] Big Mek advance: ", am.get("advance_roll", -1), " cap ", am.get("move_cap_inches", -1))
return int(am.get("advance_roll", -1))

var u = GameState.get_unit("U_BIG_MEK_A")
var ok := true
for m in u.models:
	if not m.get("alive", true) or m.get("position", null) == null:
		continue
	var p = m.position
	var r = NetworkIntegration.route_action({"type": "STAGE_MODEL_MOVE", "player": 1, "actor_unit_id": "U_BIG_MEK_A", "payload": {"model_id": str(m.id), "dest": [float(p.x) + -120.0, float(p.y) + 0.0], "rotation": float(m.get("rotation", 0.0))}})
	if not r.get("success", false):
		print("[wp-o6] stage failed ", m.id, " ", r.get("error", r.get("errors", "")))
		ok = false
tree.current_scene._recreate_unit_visuals()
return ok
